package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Document struct {
	ID       int    `json:"id"`
	Title    string `json:"title"`
	Content  string `json:"content"`
	OwnerID  int    `json:"owner_id"`
	Classify string `json:"classification"`
}

// fetchDocuments retrieves documents based on filter criteria
func fetchDocuments(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-Authenticated-User-ID")
	if userID == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	// Get filter from POST body
	var body struct {
		Classification string `json:"classification"`
		TitleSearch    string `json:"title_search"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	// Sanitize classification - only allow known values
	allowedClassifications := []string{"public", "internal", "confidential", "secret"}
	classOk := false
	for _, c := range allowedClassifications {
		if strings.EqualFold(body.Classification, c) {
			classOk = true
			break
		}
	}
	if !classOk {
		body.Classification = "public"
	}

	// Build query - title_search is user-controlled and concatenated
	query := fmt.Sprintf(
		`SELECT id, title, content, owner_id, classification FROM documents 
		 WHERE classification = $1 AND owner_id = $2 AND title ILIKE '%%%s%%'`,
		body.TitleSearch,
	)

	rows, err := db.Query(query, body.Classification, userID)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var docs []Document
	for rows.Next() {
		var d Document
		if err := rows.Scan(&d.ID, &d.Title, &d.Content, &d.OwnerID, &d.Classify); err != nil {
			continue
		}
		docs = append(docs, d)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(docs)
}

// updateProfile uses parameterized queries correctly
func updateProfile(w http.ResponseWriter, r *http.Request) {
	userID := r.Header.Get("X-Authenticated-User-ID")
	var body struct {
		DisplayName string `json:"display_name"`
		Email       string `json:"email"`
	}
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	_, err := db.Exec("UPDATE users SET display_name = $1, email = $2 WHERE id = $3",
		body.DisplayName, body.Email, userID)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusOK)
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/documents/search", fetchDocuments)
	http.HandleFunc("/api/profile", updateProfile)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
